import json
from pathlib import Path
p=Path(__file__).parent/'chunks/0003.json';d=json.loads(p.read_text())
translations={
 't000024': '''Fără posibilitatea de a exprima gânduri sau sentimente proprii, individualitatea însăși începe să se erodeze. Oamenii ajung să gândească mai asemănător și devin mai ușor de controlat și îndrumat de Partid.''',
 't000025': '''Dispariția anumitor cuvinte și concepte din limbă înseamnă și pierderea memoriei istorice și culturale. Ideile care nu pot fi exprimate în cuvinte dispar treptat din conștiința colectivă, izolând și mai mult fiecare generație de trecutul ei.''',
 't000026': '''Explorarea controlului lingvistic în „1984” reprezintă un avertisment puternic al lui Orwell despre legătura dintre limbaj și gândire. Arătând cum manipularea limbii poate limita libertatea cognitivă, el subliniază importanța protejării diversității lingvistice și a dreptului la liberă exprimare. Romanul ne îndeamnă să ne gândim cum ne modelează limba percepția realității și capacitatea de a gândi critic. În epoca mesajelor scurte, a rețelelor sociale și a supraîncărcării informaționale, observațiile lui Orwell despre puterea limbajului rămân profund relevante.''',
 't000027': 'Capitolul al treilea: Relațiile umane și rezistența',
 't000028': '''În lumea opresivă a Oceaniei, relațiile umane capătă o dimensiune complexă și adesea primejdioasă. „1984” de George Orwell arată cum iubirea, prietenia și legăturile de familie sunt afectate de regimul totalitar și cum aceste relații pot deveni forme de rezistență față de controlul Partidului.''',
 't000029': '''Relația dintre Winston Smith și Julia formează nucleul emoțional al romanului. Legătura lor nu este doar o poveste de dragoste, ci și un act de rebeliune politică. Într-o societate în care loialitatea personală trebuie îndreptată exclusiv către Partid și Fratele cel Mare, apropierea lor amenință ordinea existentă.''',
 't000030': '''Relația dintre Winston și Julia începe cu prudență, prin priviri pe furiș și un bilețel secret. Pe măsură ce se apropie, își creează o lume privată, departe de privirile teleecranelor. Camera închiriată deasupra prăvăliei domnului Charrington devine un refugiu în care pot fi ei înșiși, eliberați de rolul pe care trebuie să îl joace permanent ca membri ai Partidului.''',
 't000031': '''Intimitatea lor fizică este ea însăși un act de sfidare. Partidul privește sexul numai ca pe o datorie de procreare, lipsită de plăcere sau legătură afectivă. Găsind bucurie și alinare unul în apropierea celuilalt, Winston și Julia resping încercarea Partidului de a controla până și cele mai elementare instincte umane.''',
 't000032': '''Totuși, relația lor este mereu umbrită de convingerea că vor fi descoperiți. Teama de trădare plutește asupra lor, venind nu doar din afară, ci și din relația dintre ei. Winston se întreabă dacă Julia ar putea fi agentă a Poliției Gândirii, în timp ce ea pare mai pragmatică în privința capturării lor inevitabile. Această tensiune arată cum regimul de frică și suspiciune al Partidului infectează până și cele mai intime legături.''',
 't000033': '''Spre deosebire de legătura pasională cu Julia, relația lui Winston cu O’Brien este mai complicată și, în cele din urmă, devastatoare. Pentru Winston, O’Brien reprezintă speranța că și în Partid există oameni care se opun în secret conducerii sale. Dorința de a avea încredere în el, în ciuda riscurilor, arată nevoia profund umană de legătură și de scop împărtășit, mai ales în fața opresiunii.''',
 't000034': '''Trădarea lui O’Brien amintește brutal de puterea și întinderea influenței Partidului. Ea distruge credința lui Winston că o legătură umană autentică ar fi posibilă sub un regim totalitar. Rolul lui O’Brien în torturarea și „reeducarea” lui Winston este cu atât mai îngrozitor cu cât acesta avusese încredere în el.''',
 't000035': '''Influența Partidului a schimbat fundamental relațiile de familie din Oceania. Copiii sunt încurajați să-și spioneze părinții și să raporteze orice urmă de comportament neortodox. Partidul folosește suspiciunea reciprocă din familii pentru a submina cele mai elementare legături sociale.''',
 't000036': '''Amintirile lui Winston despre mama și sora sa, pierdute în haosul revoluției, contrastează puternic cu viața de familie din prezent. Amintirea iubirii dezinteresate a mamei sale devine simbolul unui trecut mai uman, pe care Partidul este hotărât să îl șteargă din memorie.''',
 't000037': '''Romanul explorează și felul în care Partidul controlează și reprimă sexualitatea. Liga Tineretului Antisex promovează abstinența și privește sexul pentru plăcere ca pe un delict de gândire. Această reprimare a impulsurilor firești este o altă cale prin care Partidul încearcă să îndrepte spre sine întreaga energie și loialitate umană.''',
}
assert set(translations)=={x['id'] for x in d['segments']}
for seg in d['segments']:seg['translation']=translations[seg['id']]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('translated',len(d['segments']))
